import hashlib
import hmac
import os
import time
import json
from functools import wraps
from urllib.parse import urlparse

# Secure session framework with CSRF protection
SECRET_KEY = os.environ.get('APP_SECRET_KEY', os.urandom(32).hex())
CSRF_TOKEN_LENGTH = 32
SESSION_DURATION = 3600

class Request:
    def __init__(self, method, headers, body, cookies):
        self.method = method
        self.headers = headers or {}
        self.body = body or ''
        self.cookies = cookies or {}
        self._parsed_body = None

    @property
    def content_type(self):
        ct = self.headers.get('Content-Type', '')
        return ct.split(';')[0].strip().lower()

    @property
    def parsed_body(self):
        if self._parsed_body is None:
            if self.content_type == 'application/json':
                try:
                    self._parsed_body = json.loads(self.body)
                except (json.JSONDecodeError, TypeError):
                    self._parsed_body = {}
            elif self.content_type == 'application/x-www-form-urlencoded':
                self._parsed_body = dict(
                    item.split('=', 1) for item in self.body.split('&') if '=' in item
                )
            else:
                self._parsed_body = {}
        return self._parsed_body

    @property
    def is_xhr(self):
        return self.headers.get('X-Requested-With', '').lower() == 'xmlhttprequest'

    @property
    def origin(self):
        return self.headers.get('Origin', '')


class Response:
    def __init__(self, status=200, body='', headers=None):
        self.status = status
        self.body = body
        self.headers = headers or {}


def generate_csrf_token(session_id):
    """Generate a CSRF token bound to the session."""
    timestamp = int(time.time())
    payload = f"{session_id}:{timestamp}".encode()
    signature = hmac.new(
        SECRET_KEY.encode() if isinstance(SECRET_KEY, str) else SECRET_KEY,
        payload,
        hashlib.sha256
    ).hexdigest()
    return f"{timestamp}:{signature}"


def validate_csrf_token(session_id, token, max_age=SESSION_DURATION):
    """Validate CSRF token integrity and freshness."""
    if not token or ':' not in token:
        return False
    try:
        timestamp_str, provided_sig = token.split(':', 1)
        timestamp = int(timestamp_str)
    except (ValueError, TypeError):
        return False

    # Check token age
    current_time = int(time.time())
    if current_time - timestamp > max_age:
        return False
    if timestamp > current_time + 60:  # Allow 60s clock skew
        return False

    # Verify signature
    payload = f"{session_id}:{timestamp}".encode()
    expected_sig = hmac.new(
        SECRET_KEY.encode() if isinstance(SECRET_KEY, str) else SECRET_KEY,
        payload,
        hashlib.sha256
    ).hexdigest()

    return hmac.compare_digest(provided_sig, expected_sig)


def get_session_id(request):
    """Extract and validate session ID from cookie."""
    session_cookie = request.cookies.get('session_id', '')
    if not session_cookie or len(session_cookie) != 64:
        return None
    # Verify it's a valid hex string
    try:
        bytes.fromhex(session_cookie)
    except ValueError:
        return None
    return session_cookie


class CSRFProtectionMiddleware:
    """Middleware that enforces CSRF protection on state-changing requests."""

    SAFE_METHODS = frozenset(['GET', 'HEAD', 'OPTIONS', 'TRACE'])
    # Note: We intentionally do NOT exempt any content types.
    # While some frameworks exempt application/json assuming CORS preflight
    # will block cross-origin requests, this is not reliable because:
    # 1. Misconfigured CORS policies may allow it
    # 2. Browser plugins/extensions may bypass CORS
    # 3. navigator.sendBeacon can send certain payloads cross-origin
    # We require CSRF tokens for ALL state-changing requests regardless of content type.

    def __init__(self, app, config=None):
        self.app = app
        self.config = config or {}
        self._trusted_origins = self.config.get('trusted_origins', [])
        self._enforce_origin_check = self.config.get('enforce_origin', True)

    def _is_safe_method(self, request):
        return request.method.upper() in self.SAFE_METHODS

    def _check_origin(self, request):
        """Verify the Origin header matches trusted origins."""
        origin = request.origin
        if not origin:
            # No origin header - could be same-origin or non-browser
            # We still require CSRF token validation below
            return True
        parsed = urlparse(origin)
        origin_host = parsed.netloc
        return origin_host in self._trusted_origins

    def _validate_csrf(self, request, session_id):
        """Extract and validate CSRF token from request."""
        # Check header first (preferred for AJAX)
        token = request.headers.get('X-CSRF-Token', '')
        if not token:
            # Fall back to body parameter
            token = request.parsed_body.get('csrf_token', '')
        return validate_csrf_token(session_id, token)

    def process_request(self, request):
        """Main CSRF validation logic."""
        # Safe methods don't need CSRF protection
        if self._is_safe_method(request):
            return None  # Continue processing

        # Get session
        session_id = get_session_id(request)
        if session_id is None:
            return Response(status=401, body='Unauthorized: No valid session')

        # Origin check (defense in depth)
        if self._enforce_origin_check and not self._check_origin(request):
            return Response(status=403, body='Forbidden: Origin check failed')

        # CSRF token validation - required for ALL state-changing requests
        if not self._validate_csrf(request, session_id):
            return Response(status=403, body='Forbidden: CSRF validation failed')

        return None  # Continue processing


# Application handlers
def transfer_funds(request):
    """Transfer funds between accounts - requires authentication."""
    session_id = get_session_id(request)
    if not session_id:
        return Response(status=401, body='Unauthorized')

    data = request.parsed_body
    to_account = data.get('to_account', '')
    amount = data.get('amount', 0)

    if not to_account or not amount:
        return Response(status=400, body='Missing required fields')

    try:
        amount = float(amount)
        if amount <= 0 or amount > 1000000:
            return Response(status=400, body='Invalid amount')
    except (ValueError, TypeError):
        return Response(status=400, body='Invalid amount format')

    # Process transfer (simulated)
    result = {
        'status': 'success',
        'from_session': session_id[:8] + '...',
        'to_account': to_account,
        'amount': amount,
        'timestamp': int(time.time())
    }
    return Response(status=200, body=json.dumps(result))


def change_email(request):
    """Change user email - requires authentication."""
    session_id = get_session_id(request)
    if not session_id:
        return Response(status=401, body='Unauthorized')

    data = request.parsed_body
    new_email = data.get('email', '')

    if not new_email or '@' not in new_email:
        return Response(status=400, body='Invalid email')

    result = {'status': 'success', 'email': new_email}
    return Response(status=200, body=json.dumps(result))


# Application setup
def create_app():
    config = {
        'trusted_origins': ['localhost:8080', 'myapp.example.com'],
        'enforce_origin': True,
    }
    middleware = CSRFProtectionMiddleware(None, config)

    routes = {
        '/api/transfer': transfer_funds,
        '/api/change-email': change_email,
    }

    def handle_request(request):
        # Run CSRF middleware
        csrf_response = middleware.process_request(request)
        if csrf_response:
            return csrf_response

        # Route to handler
        path = request.headers.get('X-Path', '/')
        handler = routes.get(path)
        if handler:
            return handler(request)
        return Response(status=404, body='Not found')

    return handle_request
